import { useState, type ReactNode } from "react";
import { Box } from "@/shared/ui/layout/Box";
import { Row } from "@/shared/ui/layout/Row";
import { Stack } from "@/shared/ui/layout/Stack";
import { DataTableHeader } from "@/shared/ui/data/DataTableRow";
import { KeyValueList } from "@/shared/ui/data/KeyValueList";
import { PageHeader } from "@/shared/ui/pages/PageHeader";
import { Skeleton } from "@/shared/ui/feedback/Skeleton";
import { EmptyState } from "@/shared/ui/feedback/EmptyState";
import { useDragResize } from "@/shared/hooks/useDragResize";

function DataTableRow({ template, children, index, selected, onClick }: { template: string; children: ReactNode; index?: number; selected?: boolean; onClick?: () => void }) {
  return (
    <div
      className={"dt-row" + (selected ? " selected" : "") + (index != null && index % 2 ? " odd" : "")}
      style={{ display: "grid", gridTemplateColumns: template, cursor: onClick ? "pointer" : undefined }}
      onClick={onClick}
    >
      {children}
    </div>
  );
}
function SplitView({ primary, secondary, secondarySize = 340, secondaryMin = 200, secondaryMax = 640, toolbar, className }: {
  primary: ReactNode; secondary: ReactNode; secondarySize?: number; secondaryMin?: number; secondaryMax?: number; toolbar?: ReactNode; className?: string;
}) {
  const drag = useDragResize({ initial: secondarySize, min: secondaryMin, max: secondaryMax, axis: "x", invert: true });
  const size = Math.min(Math.max(drag.size, secondaryMin), Math.min(secondaryMax, 480));
  return (
    <Stack gap={0} className={className} style={{ flex: 1, minHeight: 0, overflow: "hidden" }}>
      {toolbar}
      <Row gap={0} align="stretch" style={{ flex: 1, minHeight: 0, minWidth: 0, overflow: "hidden" }}>
        <Box style={{ flex: 1, minWidth: 0, minHeight: 0, display: "flex", flexDirection: "column", overflow: "hidden", borderRight: "1px solid var(--border-soft)" }}>
          {primary}
        </Box>
        <Box className="resize-x" title="Drag to resize" {...drag.handleProps} />
        <Box style={{ flex: `0 0 ${size}px`, width: size, maxWidth: "45%", minWidth: 0, minHeight: 0, display: "flex", flexDirection: "column", overflow: "hidden" }}>
          {secondary}
        </Box>
      </Row>
    </Stack>
  );
}

export interface TablePageColumn {
  key: string;
  label: string;
  width?: string;
}
export interface TablePageRow {
  id: string;
  cells: Record<string, ReactNode>;
}
export interface TablePageProps {
  title?: ReactNode;
  hint?: ReactNode;
  toolbar?: ReactNode;
  columns?: TablePageColumn[];
  rows?: TablePageRow[];
  selectedId?: string | null;
  defaultSelectedId?: string;
  onSelect?: (id: string) => void;
  detail?: (row: TablePageRow) => ReactNode;
  detailWidth?: number;
  className?: string;
  loading?: boolean;
}
const DEMO_COLUMNS: TablePageColumn[] = [
  { key: "name", label: "Session" },
  { key: "state", label: "State", width: "90px" },
];
const DEMO_ROWS: TablePageRow[] = [
  { id: "a", cells: { name: "planner", state: "run" } },
  { id: "b", cells: { name: "worker-api", state: "idle" } },
];
export function TablePage({
  title = "Sessions", hint, toolbar,
  columns = DEMO_COLUMNS, rows = DEMO_ROWS,
  selectedId, defaultSelectedId = "a", onSelect,
  detail, detailWidth = 320, className, loading = false,
}: TablePageProps) {
  const controlled = selectedId !== undefined;
  const [innerSelected, setInnerSelected] = useState<string | null>(defaultSelectedId ?? null);
  const selected = controlled ? selectedId : innerSelected;
  const select = (id: string) => {
    if (!controlled) setInnerSelected(id);
    onSelect?.(id);
  };
  const template = columns.map((c) => c.width ?? "1fr").join(" ");
  const row = rows.find((r) => r.id === selected);

  return (
    <SplitView
      className={className}
      toolbar={<PageHeader title={title} hint={hint} toolbar={toolbar} meta={String(rows.length)} />}
      secondarySize={detailWidth}
      primary={
        <Box pad={16} style={{ flex: 1, minWidth: 0, minHeight: 0, overflow: "auto" }}>
          {loading ? (
            <Stack gap={8}>
              {Array.from({ length: 6 }).map((_, i) => <Skeleton key={i} h={22} radius={5} />)}
            </Stack>
          ) : (
          <>
          <DataTableHeader template={template}>
            {columns.map((c) => (
              <span key={c.key} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{c.label}</span>
            ))}
          </DataTableHeader>
          {rows.map((r, i) => (
            <DataTableRow key={r.id} template={template} index={i} selected={selected === r.id} onClick={() => select(r.id)}>
              {columns.map((c) => (
                <span key={c.key} style={{ overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap" }}>{r.cells[c.key]}</span>
              ))}
            </DataTableRow>
          ))}
          {rows.length === 0 && (
            <EmptyState title="No records" description="Rows appear here as the collection fills." />
          )}
          </>
          )}
        </Box>
      }
      secondary={
        <Box pad={16} style={{ flex: 1, minWidth: 0, minHeight: 0, overflowY: "auto", display: "flex", flexDirection: "column" }}>
          {row ? (
            detail ? detail(row) : (
              <Stack gap={12}>
                <div style={{ fontSize: 14, fontWeight: 600 }}>{row.cells[columns[0] ? columns[0].key : ""]}</div>
                <KeyValueList items={columns.map((c) => ({ k: c.label, v: row.cells[c.key] }))} />
              </Stack>
            )
          ) : (
            <EmptyState title="No record selected" description="Select a row to inspect its fields." />
          )}
        </Box>
      }
    />
  );
}

